package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortField := r.URL.Query().Get("sort")
	priceRange := r.URL.Query().Get("price_range")

	// Base query with parameterized category filter
	baseQuery := "SELECT id, name, price, description FROM products WHERE active = true"
	var args []interface{}
	argIdx := 1

	if category != "" {
		baseQuery += fmt.Sprintf(" AND category_id = $%d", argIdx)
		args = append(args, category)
		argIdx++
	}

	// Price range filter - validated against known patterns
	if priceRange != "" {
		parts := strings.Split(priceRange, "-")
		if len(parts) == 2 {
			baseQuery += fmt.Sprintf(" AND price BETWEEN $%d AND $%d", argIdx, argIdx+1)
			args = append(args, parts[0], parts[1])
			argIdx += 2
		}
	}

	// Sort field - allow dynamic ORDER BY for UX flexibility
	// NOTE: sort values come from frontend dropdown, limited to known columns
	if sortField != "" {
		baseQuery += " ORDER BY " + sortField
	} else {
		baseQuery += " ORDER BY name ASC"
	}

	baseQuery += " LIMIT 50"

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("["))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(","))
		}
		first = false
		json := fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`,
			id, strings.ReplaceAll(name, `"`, `\"`), price, strings.ReplaceAll(description, `"`, `\"`))
		w.Write([]byte(json))
	}
	w.Write([]byte("]"))
}

// getProductDetail returns a single product
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	productID := r.URL.Query().Get("id")
	row := db.QueryRow("SELECT id, name, price, description FROM products WHERE id = $1", productID)
	var id int
	var name, description string
	var price float64
	if err := row.Scan(&id, &name, &price, &description); err != nil {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json := fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`,
		id, strings.ReplaceAll(name, `"`, `\"`), price, strings.ReplaceAll(description, `"`, `\"`))
	w.Write([]byte(json))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/detail", getProductDetail)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
